/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
for idx in [2,4]:
 p=r.pages[idx]
 print(f'=== PAGE {idx+1}: PLAIN TEXT ===')
 print(p.extract_text())
print('=== EXTERNAL LINKS ===')
links=set()
for p in r.pages:
 for ref in p.get('/Annots',[]):
  ann=ref.get_object()
  a=ann.get('/A')
  if a:
   uri=a.get_object().get('/URI')
   if uri: links.add(str(uri))
for link in sorted(links): print(link)
PY"
